import{_ as i,l as r,o as e,c as l,v as o,p as s,x as t,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"单调与局部非饱和","description":"","frontmatter":{"title":"单调与局部非饱和","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/monotonicity-lns.md","filePath":"econ/monotonicity-lns.md","lastUpdated":1789023840000}'),E={name:"econ/monotonicity-lns.md"};function h(m,a,_,A,u,B){const n=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="单调与局部非饱和" tabindex="-1">单调与局部非饱和 <a class="header-anchor" href="#单调与局部非饱和" aria-label="Permalink to &quot;单调与局部非饱和&quot;">​</a></h1><div class="epigraph"><p>局部非饱和排除幸福点：任意消费束的附近，总还有更好的束。单调则把「附近更好」写成「更多更好」。</p><footer>—— 据 Mas-Colell, Whinston and Green, Microeconomic Theory 第 2–3 章；Varian, Microeconomic Analysis 整理</footer></div><p>上一课<a href="/econ/continuity-preference">连续性</a>给了闭优集：紧菜单上最大元非空，连续表示有了拓扑前提。本课不重讲上、下优集，也不再举词典序。缺口是：连续理性仍允许「多多更差」。没有一条「附近总有更好」，最优可以落在预算内部，后课的瓦尔拉斯定律会漏一项。本课只加单调与局部非饱和。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>连续偏好可以有幸福点：某个 \\(\\bar x\\) 在一个开邻域里最好。预算若把这个点包在内部，钱花不完，\\(p\\cdot x\\lt w\\)。对偶里支出与财富对不上，超额需求加总也不再落在超平面上。缺口不是再要一次连续性，而是排除饱和。</p><p>局部非饱和：对每个 \\(x\\) 与每个邻域，存在 \\(y\\) 使 \\(y\\succ x\\)。弱单调：\\(x\\ge y\\) 蕴含 \\(x\\succsim y\\)。严格单调：\\(x\\gg y\\) 蕴含 \\(x\\succ y\\)。单调（再加一点正则）蕴含局部非饱和；反过来，局部非饱和不强迫所有商品都是「多多益善」——有害品可以存在，只要附近总能挪到更好的点。后课预算最大化真正用的是弱的那条。</p><h3 id="花光预算不是节俭-是附近还有更好" tabindex="-1">花光预算不是节俭，是附近还有更好 <a class="header-anchor" href="#花光预算不是节俭-是附近还有更好" aria-label="Permalink to &quot;花光预算不是节俭，是附近还有更好&quot;">​</a></h3><p>局部非饱和下，内部点不可能最优：稍花一点剩下的钱就能严格改善。因此最优必在边界，\\(p\\cdot x=w\\)。这就是后课要引用的瓦尔拉斯定律。它不是道德，是公理推出来的会计。</p><p><span class="marginnote">「饱和」是幸福点；「非饱和」是任意点附近仍有改善。中文教材亦称局部非餍足。本课用标题里的非饱和，对象与 MWG 同一条。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 \\(X=\\mathbb{R}_+^n\\)。连续、理性、局部非饱和的偏好，在 \\(p\\gg 0\\)、\\(w\\gt 0\\) 的预算上：若最大元存在，则落在 \\(p\\cdot x=w\\) 上。无界预算仍可能没有最大元——单调者会沿某方向走到无穷——后课用价格严格为正和紧化处理。本课不定义马歇尔需求，只把「最优 ⇒ 花光」钉死。</p><p>单调给出更强的几何：更好的一侧是「更多」的那一侧，免费赠品不会被扔掉。弱单调允许某些坐标完全无感；严格单调要求所有坐标同时增加才严格变好，排除中性品。局部非饱和比二者都弱、也更适合当工作假说：它允许中性品、允许有害品，只要没有开集幸福点。Varian 写需求、MWG 写瓦尔拉斯定律，用的都是这条弱条件，而不是把「多多益善」写成公理清单。</p>',12)),(e(),s(d,null,{default:t(()=>[c(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E8%BF%9E%E7%BB%AD%E7%90%86%E6%80%A7%E5%81%8F%E5%A5%BD%22%5D%20--%3E%20MON%5B%22%E5%8D%95%E8%B0%83%EF%BC%9A%E6%9B%B4%E5%A4%9A%E4%B8%8D%E6%9B%B4%E5%B7%AE%22%5D%0A%20%20C%20--%3E%20LNS%5B%22%E5%B1%80%E9%83%A8%E9%9D%9E%E9%A5%B1%E5%92%8C%22%5D%0A%20%20MON%20--%3E%20LNS%0A%20%20LNS%20--%3E%20W%5B%22%E6%9C%80%E4%BC%98%E5%A4%84%E8%8A%B1%E5%85%89%E9%A2%84%E7%AE%97%22%5D%0A%20%20W%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%93%A6%E5%B0%94%E6%8B%89%E6%96%AF%E5%AE%9A%E5%BE%8B%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>严格单调还会排除边界上的「某种商品零价格仍不想要」的某些角点，但角点本身是<a href="/econ/interior-corner">内点与角点</a>的缺口。本课不写 Kuhn–Tucker。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了局部非饱和，钱是约束而不是装饰。间接效用对财富严格递增（在内部财富处）；支出函数达到给定效用时账单被用尽。后课罗伊恒等式里的 \\(\\partial v/\\partial w\\) 才不会是零。一般均衡里，每人 \\(p\\cdot x_i(p)=p\\cdot\\omega_i\\)，加总成瓦尔拉斯法则。没有非饱和，最优可以剩钱，这条加总会计会少一项，存在性证明里超额需求也不再正交于价格。</p><p>单调把免费物送进最优集：若 \\(p_j=0\\) 且偏好对该商品严格递增，需求可以无界。这是后课存在性证明为什么要 \\(p\\gg 0\\) 或把价格收到单纯形内部。本课只指出：连续性不够，还要「方向」——更好的方向至少不是「全部更少」。</p><p><span class="marginnote">凸性仍未进场。局部非饱和的偏好可以讨厌平均：无差异集可以凹向原点。需求集值、均衡存在更脆，是下一课的缺口。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>局部非饱和是工作假说，不是普遍事实。毒品、容量约束、生理上限都会造出局部幸福点；那时钱可以剩，瓦尔拉斯定律改成不等式。主干仍用非饱和，因为对偶与一般均衡都靠它把预算变成等式。</p><p>也不要把单调读成「所有商品都好」。垃圾、噪音可以是负商品，模型把它们写成正商品的减少，或直接允许某坐标违反单调。局部非饱和只要在某个方向上还能改善。实验里的餍足、禀赋效应是对照，不把本课改成心理学。</p><p>免费处置与单调也不是同一句话。生产一侧的自由处置说可行集向「更少」闭；消费一侧的单调说排序向「更多」升。本课只管消费者。零价格时二者会在存在性证明里碰头，那是均衡课的缺口。</p><p>后课默认：消费者局部非饱和，最优花光预算。马歇尔需求、间接效用都在这条等式上写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>连续理性仍允许幸福点；局部非饱和排除开集里的最大元。</li><li>单调是更强的「多多不更差」；它蕴含局部非饱和，但非饱和更常用。</li><li>非饱和 ⇒ 最优在预算边界，后课称瓦尔拉斯定律。</li><li>凸性、角点一阶条件尚未出场。</li><li>出处：Mas-Colell, Whinston and Green 第 2–3 章；Varian, <em>Microeconomic Analysis</em>。</li></ul>',12))])}const b=i(E,[["render",h]]);export{f as __pageData,b as default};
